50	                .andExpect(jsonPath("$.id").isNumber())
51	                .andExpect(jsonPath("$.instrumentId").value("INS-1"))
52	                .andExpect(jsonPath("$.a").value("1.5"))
53	                .andExpect(jsonPath("$.b").value("0.25"))
