package com.example.starter.calibration.service;

import java.time.Instant;

/**
 * 业务时钟：系数版本生效区间的判定以此为“当前时刻”。
 * 生产环境使用系统 UTC 时钟；测试可注入固定/可控时钟验证左闭右开边界。
 */
public interface BusinessClock {

    /** 当前时刻（UTC）。 */
    Instant now();
}

package com.example.starter.calibration.service;

import java.time.Instant;

import org.springframework.stereotype.Component;

/**
 * 系统 UTC 时钟：生产环境使用。
 */
@Component
public class SystemBusinessClock implements BusinessClock {

    @Override
    public Instant now() {
        return Instant.now();
    }
}

package com.example.starter.calibration.model;

import java.time.Instant;

/**
 * 放行请求快照。requestId 全局唯一支撑重放幂等；
 * 同一 requestId 重放时请求指纹（放行人＋各测量环境读数摘要）必须与首次一致，否则判定为冲突。
 *
 * @param id         放行请求 ID（幂等键）
 * @param batchId    首次放行生成的批次 ID（UUID）
 * @param releasedBy 首次放行人（X-Actor-Id）
 * @param fingerprint 请求指纹 SHA-256 十六进制摘要
 * @param releasedAt 首次放行时间（UTC）
 */
public record ReleaseRequestSnapshot(
        String id,
        String batchId,
        String releasedBy,
        String fingerprint,
        Instant releasedAt) {
}

